import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.next();
        scanner.close();

        StringBuilder solve = new StringBuilder();
        int N = s.length();

        for (int i = 0; i < N; ++i) {
            if (i + 3 <= N && s.substring(i, i + 3).equals("dot")) {
                solve.append(".");
                i += 2;
            } else if (i + 2 <= N && s.substring(i, i + 2).equals("at")) {
                solve.append("@");
                i += 1;
            } else {
                solve.append(s.charAt(i));
            }
        }

        check(solve);

        int countAt = 0;
        for (int i = 0; i < solve.length(); ++i) {
            if (solve.charAt(i) == '@') countAt++;
        }

        if (countAt == 1) {
            System.out.println(solve.toString());
        } else {
            boolean firstAt = true;
            StringBuilder result = new StringBuilder();
            for (int i = 0; i < solve.length(); ++i) {
                char c = solve.charAt(i);
                if (c == '@') {
                    if (firstAt) {
                        result.append('@');
                        firstAt = false;
                    } else {
                        result.append("at");
                    }
                } else {
                    result.append(c);
                }
            }
            System.out.println(result.toString());
        }
    }

    static void check(StringBuilder solve) {
        if (solve.length() == 0) return;

        if (solve.charAt(0) == '.') {
            solve.deleteCharAt(0);
            solve.insert(0, "dot");
        } else if (solve.charAt(0) == '@') {
            solve.deleteCharAt(0);
            solve.insert(0, "at");
        }

        if (solve.length() == 0) return;

        int lastIdx = solve.length() - 1;
        if (solve.charAt(lastIdx) == '.') {
            solve.deleteCharAt(lastIdx);
            solve.append("dot");
        } else if (solve.charAt(lastIdx) == '@') {
            solve.deleteCharAt(lastIdx);
            solve.append("at");
        }
    }
}

