        StringBuilder solve = new StringBuilder();
        int i = 0;
        while (i < N) {
            if (i + 3 <= N) {
                if (s.substring(i, i + 3).equals("dot")) {
                    solve.append('.');
                    i += 3;
                } else {
                    if (i + 2 <= N && s.substring(i, i + 2).equals("at")) {
                        solve.append('@');
                        i += 2;
                    } else {
                        solve.append(s.charAt(i));
                        i++;
                    }
                }
            } else if (i + 2 <= N) {
                if (s.substring(i, i + 2).equals("at")) {
                    solve.append('@');
                    i += 2;
                } else {
                    solve.append(s.charAt(i));
                    i++;
                }
            } else {
                solve.append(s.charAt(i));
                i++;
            }
        }

        String str = solve.toString();
        if (!str.isEmpty()) {
            if (str.charAt(0) == '.') {
                str = "dot" + str.substring(1);
            } else if (str.charAt(0) == '@') {
                str = "at" + str.substring(1);
            }
            if (!str.isEmpty()) {
                char last = str.charAt(str.length() - 1);
                if (last == '.') {
                    str = str.substring(0, str.length() - 1) + "dot";
                } else if (last == '@') {
                    str = str.substring(0, str.length() - 1) + "at";
                }
            }
        }

        int cont = 0;
        for (char c : str.toCharArray()) {
            if (c == '@') cont++;
        }

        if (cont == 1) {
            System.out.println(str);
        } else {
            StringBuilder output = new StringBuilder();
            boolean ok = true;
            for (char c : str.toCharArray()) {
                if (c == '@') {
                    if (ok) {
                        output.append('@');
                        ok = false;
                    } else {
                        output.append("at");
                    }
                } else {
                    output.append(c);
                }
            }
            System.out.println(output.toString());
        }
    }
}

