    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();

        StringBuilder solve = new StringBuilder();
        int N = s.length();

        for (int i = 0; i < N; ++i) {
            if (i + 3 <= N && s.substring(i, i + 3).equals("dot")) {
                solve.append(".");
                i += 2;
            } else if (i + 2 <= N && s.substring(i, i + 2).equals("at")) {
                solve.append("@");
                i += 1;
            } else {
                solve.append(s.charAt(i));
            }
        }

        check(solve);

        int cont = 0;
        for (int i = 0; i < solve.length(); ++i) {
            if (solve.charAt(i) == '@') cont++;
        }

        if (cont == 1) {
            System.out.println(solve.toString());
        } else {
            boolean ok = true;
            StringBuilder output = new StringBuilder();
            for (int i = 0; i < solve.length(); ++i) {
                char c = solve.charAt(i);
                if (c == '@') {
                    if (ok) {
                        output.append('@');
                        ok = false;
                    } else {
                        output.append("at");
                    }
                } else {
                    output.append(c);
                }
            }
            System.out.println(output.toString());
        }
    }

    static void check(StringBuilder solve) {
        if (solve.length() > 0) {
            if (solve.charAt(0) == '.') {
                solve.deleteCharAt(0);
                solve.insert(0, "dot");
